<template><admin-layout><admin-review-panel><a class="review-link" :href="route('admin.merchant.earnings')">← {{ $t('Back') }}</a><h1>{{ merchant.business_name }} · {{ $t('Earnings') }}</h1><dl class="review-grid"><div v-for="entry in metrics" :key="entry[0]"><dt>{{ $t(entry[0]) }}</dt><dd>{{ entry[1] }}</dd></div></dl><h2>{{ $t('Recent invoices') }}</h2><div class="review-scroll"><table><thead><tr><th>ID</th><th>{{ $t('Status') }}</th><th>{{ $t('Amount') }} (USD)</th><th>{{ $t('Date') }}</th></tr></thead><tbody><tr v-for="r in recentInvoices" :key="r.id"><td>{{ r.id }}</td><td>{{ $t(r.status) }}</td><td>{{ r.amount_usd }}</td><td>{{ r.paid_at }}</td></tr><tr v-if="!recentInvoices.length"><td colspan="4">{{ $t('No records') }}</td></tr></tbody></table></div><h2>{{ $t('Recent payouts') }}</h2><div class="review-scroll"><table><thead><tr><th>ID</th><th>{{ $t('Status') }}</th><th>{{ $t('Amount') }} (USD)</th><th>{{ $t('Date') }}</th></tr></thead><tbody><tr v-for="r in recentPayouts" :key="r.id"><td><a :href="route('admin.merchant.payouts.show',r.id)">{{ r.id }}</a></td><td>{{ $t(r.status) }}</td><td>{{ r.amount_usd }}</td><td>{{ r.created_at }}</td></tr><tr v-if="!recentPayouts.length"><td colspan="4">{{ $t('No records') }}</td></tr></tbody></table></div><h2>{{ $t('Monthly breakdown') }}</h2><div class="review-scroll"><table><thead><tr><th>{{ $t('Month') }}</th><th>{{ $t('Volume') }} (USD)</th><th>{{ $t('Fees') }} (USD)</th><th>{{ $t('Earnings') }} (USD)</th></tr></thead><tbody><tr v-for="r in monthlyData" :key="r.month"><td>{{ r.month }}</td><td>{{ r.volume }}</td><td>{{ r.fees }}</td><td>{{ r.earnings }}</td></tr></tbody></table></div></admin-review-panel></admin-layout></template>
<script>
import AdminLayout from '@/Layouts/AdminLayout';import AdminReviewPanel from '@/Components/AdminReviewPanel';import Pagination from '@/Jetstream/Pagination';
export default {components:{AdminLayout,AdminReviewPanel},props:{merchant:Object,stats:Object,recentInvoices:Array,recentPayouts:Array,monthlyData:Array},computed:{metrics(){return[['Volume',this.stats.total_volume+' USD'],['Fees',this.stats.total_fees+' USD'],['Earnings',this.stats.net_earnings+' USD'],['Available balance',this.stats.available_balance+' USD'],['Pending balance',this.stats.pending_balance+' USD'],['Paid out',this.stats.total_paid_out+' USD'],['Invoices',this.stats.paid_invoices+' / '+this.stats.total_invoices]]}}};
</script>
